steps.codeExample:
@page "/contador"

<h3>Contador: @contagem</h3>
<input @bind="nome" placeholder="Seu nome" />
<button @onclick="Somar">+1</button>

@code {
    [Parameter] public int Passo { get; set; } = 1;
    private int contagem = 0;
    private string nome = "";
    private void Somar() => contagem += Passo;
}

